create index idx_circulation
    on onshore_bond_filter_v3 (circulation_status);

create index idx_com_uni_code
    on onshore_bond_filter_v3 (com_uni_code);

create index idx_second_market
    on onshore_bond_filter_v3 (second_market);

create index idx_update_bonduni
    on onshore_bond_filter_v3 (update_time, bond_uni_code);

